// Guardar registro de ejecución
const executionData = {
  json: {
    execution_date: new Date().toISOString().split('T')[0],
    start_time: new Date().toISOString(),
    total_projects_scanned: items[0].json.length,
    status: 'running'
  }
};

return [executionData, ...items];

// Procesar cada proyecto
const executionId = items[0].json.execution_id;
const projects = items[1].json;
const results = [];
const yesterday = new Date();
yesterday.setDate(yesterday.getDate() - 1);

for (const project of projects) {
  if (project.archived) continue;

  // 1. Guardar proyecto en BD
  results.push({
    json: {
      execution_id: executionId,
      gitlab_project_id: project.id,
      project_name: project.name,
      path_with_namespace: project.path_with_namespace,
      web_url: project.web_url,
      last_activity_at: project.last_activity_at,
      created_at: project.created_at,
      metric_date: new Date().toISOString().split('T')[0]
    }
  });

  // 2. Obtener commits del proyecto (últimas 24h)
  const commitsUrl = `http://172.24.7.110/api/v4/projects/${project.id}/repository/commits?since=${yesterday.toISOString()}&per_page=100`;

  // 3. Obtener ramas
  const branchesUrl = `http://172.24.7.110/api/v4/projects/${project.id}/repository/branches`;

  results.push({
    json: {
      project_id: project.id,
      project_name: project.name,
      commits_url: commitsUrl,
      branches_url: branchesUrl,
      execution_id: executionId
    }
  });
}

return results;

// Procesar commits y calcular métricas
const executionId = items[0].json.execution_id;
const projectId = items[0].json.project_id;
const projectName = items[0].json.project_name;
const commits = items[1].json;
const branches = items[2].json;

const metrics = {
  byAuthor: {},
  byBranch: {},
  byHour: {},
  totalLines: { added: 0, deleted: 0 },
  branchCommits: {}
};

// Inicializar contadores por rama
for (const branch of branches) {
  metrics.branchCommits[branch.name] = 0;
}

// Procesar cada commit
for (const commit of commits) {
  const authorName = commit.author_name || 'Unknown';
  const authorEmail = commit.author_email || 'unknown';
  const commitDate = new Date(commit.committed_date || commit.created_at);
  const authorKey = `${authorName}<${authorEmail}>`;
  const hour = commitDate.getHours();
  const weekDay = commitDate.getDay();
  const branchName = commit.ref_name || 'main';

  // Métricas por autor
  if (!metrics.byAuthor[authorKey]) {
    metrics.byAuthor[authorKey] = {
      author_name: authorName,
      author_email: authorEmail,
      commit_count: 0
    };
  }
  metrics.byAuthor[authorKey].commit_count++;

  // Métricas por rama
  metrics.branchCommits[branchName] = (metrics.branchCommits[branchName] || 0) + 1;

  // Métricas por hora
  if (!metrics.byHour[hour]) {
    metrics.byHour[hour] = 0;
  }
  metrics.byHour[hour]++;

  // Líneas de código (si están disponibles)
  if (commit.stats) {
    metrics.totalLines.added += commit.stats.additions || 0;
    metrics.totalLines.deleted += commit.stats.deletions || 0;
  }
}

// Preparar datos para PostgreSQL
const dbOutput = [];
const today = new Date().toISOString().split('T')[0];

// 1. Commits por autor
for (const [authorKey, authorData] of Object.entries(metrics.byAuthor)) {
  dbOutput.push({
    json: {
      execution_id: executionId,
      project_id: projectId,
      author_name: authorData.author_name,
      author_email: authorData.author_email,
      commit_count: authorData.commit_count,
      metric_date: today
    }
  });
}

// 2. Commits por rama
for (const [branchName, commitCount] of Object.entries(metrics.branchCommits)) {
  if (commitCount > 0) {
    dbOutput.push({
      json: {
        execution_id: executionId,
        project_id: projectId,
        branch_name: branchName,
        commit_count: commitCount,
        metric_date: today
      }
    });
  }
}

// 3. Líneas de código
if (metrics.totalLines.added > 0 || metrics.totalLines.deleted > 0) {
  dbOutput.push({
    json: {
      execution_id: executionId,
      project_id: projectId,
      total_lines: metrics.totalLines.added + metrics.totalLines.deleted,
      added_lines: metrics.totalLines.added,
      deleted_lines: metrics.totalLines.deleted,
      metric_date: today
    }
  });
}

// 4. Frecuencia por hora
for (const [hour, count] of Object.entries(metrics.byHour)) {
  dbOutput.push({
    json: {
      execution_id: executionId,
      project_id: projectId,
      week_day: new Date().getDay(),
      hour_of_day: parseInt(hour),
      commit_count: count,
      metric_date: today
    }
  });
}

return dbOutput;
